parameters.query:
USE [{{ $('Webhook').item.json.query.database || 'TestDB' }}];
SELECT
  'view' AS _type,
  TABLE_NAME AS name
FROM INFORMATION_SCHEMA.VIEWS
ORDER BY TABLE_NAME;

parameters.jsCode:
const allItems = $input.all();
const tableRows = [];
const spRows = [];
const viewRows = [];

allItems.forEach(item => {
  const json = item.json;

  if (json.table_name && json.column_name) {
    tableRows.push(item);
  } else if (json.RoutineName || json.name) {
    if (json.created_at !== undefined) {
      spRows.push(item);
    } else {
      viewRows.push(item);
    }
  }
});

let database = 'TestDB';
try {
  database = $('Webhook').first().json.query.database || 'TestDB';
} catch (e) {
  database = 'Unknown';
}

const tablesMap = {};

tableRows.forEach(item => {
  const row = item.json;
  const tableName = row.table_name;

  if (!tableName) return;

  if (!tablesMap[tableName]) {
    tablesMap[tableName] = { name: tableName, columns: [] };
  }

  let dataType = row.data_type || '';
  if (row.max_length && row.max_length > 0) {
    const lower = dataType.toLowerCase();
    if (['varchar', 'nvarchar', 'char', 'nchar'].includes(lower)) {
      dataType += '(' + (row.max_length === -1 ? 'MAX' : row.max_length) + ')';
    }
  }

  tablesMap[tableName].columns.push({
    name: row.column_name,
    type: dataType,
    nullable: row.is_nullable === 'YES',
    isPrimaryKey: row.is_primary_key === 1,
    isForeignKey: row.is_foreign_key === 1
  });
});

const procedures = spRows
  .filter(item => item.json?.name)
  .map(item => ({ name: item.json.name }));

const views = viewRows
  .filter(item => item.json?.name)
  .map(item => ({ name: item.json.name }));

return {
  database: database,
  tables: Object.values(tablesMap),
  procedures: procedures,
  views: views,
  counts: {
    tables: Object.keys(tablesMap).length,
    procedures: procedures.length,
    views: views.length
  },
  _debug: {
    tableRows: tableRows.length,
    spRows: spRows.length,
    viewRows: viewRows.length,
    totalInput: allItems.length
  },
  timestamp: new Date().toISOString()
};
